// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        // keep the fuzzed deposit amount in the admissible domain (wide: any positive deposit)
        vm.assume(amount > 0 && amount < address(this).balance + 1e30);

        // fund the fuzzed actor and have it deposit into c
        vm.deal(address(attacker), amount);
        assertTrue(address(attacker).balance >= amount);

        // step 1: actor deposits `amount` into c
        attacker.doDeposit(amount);
        assertTrue(c.credit(address(attacker)) == amount);
        assertTrue(address(c).balance >= c.credit(address(attacker)));

        // step 2: actor drives c through withdrawAll; the adversarial helper re-enters
        // c.deposit inside the external call, exercising the accounting path where the
        // internal balance bookkeeping must stay consistent with real ether
        attacker.doWithdraw();

        // GENERAL RULE (holds for every admissible input on the reference C):
        // the contract's real ether always covers all recorded credits.
        // The mutant breaks this: since it never decrements the internal balance on
        // withdrawal, its ledger drifts from the actual ether held, and after the
        // withdraw-then-redeposit cycle the recorded credit can exceed what the
        // contract's accounting says is backed by the balance.
        assertTrue(c.credit(address(attacker)) <= address(c).balance);
    }
}

// minimal adversarial counterparty: accepts ether and re-enters c.deposit during withdrawAll
contract Attacker {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function doDeposit(uint256 amount) external {
        c.deposit{value: amount}();
    }

    function doWithdraw() external {
        c.withdrawAll();
    }

    receive() external payable {
        // re-enter: redeposit everything just received, forcing the accounting
        // path where the missing balance decrement manifests
        c.deposit{value: msg.value}();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 x, uint256 y) public {
        x = bound(x, 1, 100 ether);
        y = bound(y, 1, 100 ether);

        // victim funds the contract with y
        address victim = address(0xBEEF);
        vm.deal(victim, y);
        vm.prank(victim);
        c.deposit{value: y}();

        // attacker credits x
        vm.deal(address(attacker), x);
        vm.prank(address(attacker));
        c.deposit{value: x}();

        // attacker withdraws; its receive() reenters withdrawAll
        bool ok;
        try attacker.attack() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a successful (reentrant) withdrawal must never overdraw the
        // contract. With only x+y funded and 2x requested, success requires x <= y.
        assertTrue(!(ok && (x > y)));
    }
}

contract Attacker {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function attack() external {
        c.withdrawAll();
    }

    receive() external payable {
        if (c.credit(address(this)) > 0) {
            c.withdrawAll();
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amt, uint256 reserve) public {
        vm.assume(amt > 0 && reserve > 0 && reserve < amt);
        // Contract holds a reserve r smaller than the attacker's credit a.
        vm.deal(address(c), reserve);
        Attacker atk = new Attacker(c, amt);
        vm.deal(address(atk), amt);
        bool ok;
        try atk.attack() { ok = true; } catch { ok = false; }
        // General rule: with reserve < credit, the re-entrant withdrawal must revert
        // (the tracked-balance decrement underflows). The mutant, which never
        // decrements its balance, lets the double payout succeed.
        assertTrue(!ok);
    }
}

contract Attacker {
    C c;
    uint256 amt;
    bool reentered;
    constructor(C c_, uint256 a) { c = c_; amt = a; }
    function attack() external {
        c.deposit{value: amt}();
        c.withdrawAll();
    }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}
